#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
╔═══════════════════════════════════════════════════════╗
║       智能阅卷系统 - 一键安装器                        ║
║       双击此文件即可安装到本地                          ║
╚═══════════════════════════════════════════════════════╝

使用方法：
  1. 确保已安装 Python 3.9+
     下载：https://www.python.org/downloads/
     安装时务必勾选 "Add Python to PATH"
  2. 双击此文件
  3. 输入安装目录（默认 F:\grading-system）
  4. 自动安装依赖并启动
"""

import os
import sys
import io
import base64
import zipfile
import subprocess
import socket

# ═══════════════════════════════════════
# 项目数据（ZIP压缩后Base64编码）
# ═══════════════════════════════════════
PROJECT_ZIP_B64 = """

"""

def get_local_ip():
    """获取本机局域网IP"""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(('8.8.8.8', 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except:
        return '127.0.0.1'

def main():
    print()
    print("=" * 56)
    print("        智能阅卷系统 - 一键安装器")
    print("=" * 56)
    print()

    # ─── 确定安装目录 ───
    if len(sys.argv) > 1:
        install_dir = sys.argv[1]
    else:
        if sys.platform == "win32":
            if os.path.exists("F:\\"):
                default = "F:\\grading-system"
            else:
                default = "C:\\grading-system"
        else:
            default = os.path.expanduser("~/grading-system")

        user_input = input(f"安装目录（回车使用 {default}）：").strip()
        install_dir = user_input if user_input else default

    # ─── 解压项目文件 ───
    print(f"\n安装目录：{install_dir}")
    print("正在安装文件...")

    zip_bytes = base64.b64decode(PROJECT_ZIP_B64)
    zip_buffer = zipfile.ZipFile(io.BytesIO(zip_bytes))

    count = 0
    for info in zip_buffer.infolist():
        if info.filename.endswith("/"):
            os.makedirs(os.path.join(install_dir, info.filename), exist_ok=True)
            continue
        target = os.path.join(install_dir, info.filename)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with zip_buffer.open(info) as src, open(target, "wb") as dst:
            dst.write(src.read())
        count += 1

    print(f"  已安装 {count} 个文件")

    # ─── 安装Python依赖 ───
    print("\n正在安装依赖包（首次约1-3分钟）...")
    req_file = os.path.join(install_dir, "requirements.txt")
    try:
        subprocess.check_call([
            sys.executable, "-m", "pip", "install",
            "-r", req_file, "-q",
            "--disable-pip-version-check",
            "-i", "https://pypi.tuna.tsinghua.edu.cn/simple"
        ])
        print("  依赖安装完成")
    except subprocess.CalledProcessError:
        print("  [!] 部分依赖安装失败，尝试默认源...")
        try:
            subprocess.check_call([
                sys.executable, "-m", "pip", "install",
                "-r", req_file, "-q",
                "--disable-pip-version-check"
            ])
            print("  依赖安装完成")
        except:
            print("  [!] 依赖安装失败，启动时会自动重试")

    # ─── Windows防火墙放行 ───
    if sys.platform == "win32":
        print("\n配置防火墙...")
        try:
            subprocess.call([
                "netsh", "advfirewall", "firewall", "delete",
                "rule", "name=智能阅卷系统"
            ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            subprocess.call([
                "netsh", "advfirewall", "firewall", "add",
                "rule", "name=智能阅卷系统", "dir=in",
                "action=allow", "protocol=TCP", "localport=5000"
            ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            print("  防火墙已放行5000端口")
        except:
            print("  [!] 防火墙配置需管理员权限，可稍后手动配置")

    # ─── 完成 ───
    local_ip = get_local_ip()
    print()
    print("=" * 56)
    print("  安装成功！")
    print()
    print("  启动方式：")
    if sys.platform == "win32":
        print(f"    双击 {install_dir}\\启动阅卷系统.bat")
    else:
        print(f"    cd {install_dir} && python3 app.py")
    print()
    print("  电脑访问：http://127.0.0.1:5000")
    print(f"  手机访问：http://{local_ip}:5000")
    print("  管理员：admin / admin123")
    print("=" * 56)
    print()

    # ─── 询问启动 ───
    start = input("是否立即启动？(Y/n)：").strip().lower()
    if start != "n":
        print("\n正在启动智能阅卷系统...")
        os.chdir(install_dir)
        subprocess.call([sys.executable, "app.py"])

if __name__ == "__main__":
    main()
